import type { CompanionId } from "@/lib/companions";

/**
 * Living Leela: one interactive, source-linked scene per companion.
 *
 * Each scene is a small graph of "moments". A moment has a short retelling (our own summary,
 * clearly labelled as not scripture) and the ids of the verified passages it is based on. Choices
 * only change what the person explores next (or a closer look at one moment); every path follows
 * the story as the text tells it and reaches the same ending. Nothing here is generated by an AI.
 * tests/unit/leela.test.ts checks that every passage exists, every moment is reachable and every
 * path can reach the end.
 */

export interface LeelaChoice {
  label: string;
  to: string;
}

export interface LeelaMoment {
  id: string;
  title: string;
  /** Our own short summary of the passages (not scripture, not AI-generated). */
  retelling: string;
  /** Verified passage ids this moment is based on, in reading order. */
  passages: string[];
  /** A question the person can take to the companion in the chat (pre-filled, never auto-sent). */
  ask: string;
  choices: LeelaChoice[];
  /** A "closer look" side moment (shown as a detour, then back to the story). */
  detour?: boolean;
}

export interface LeelaScene {
  id: string;
  companion: CompanionId;
  title: string;
  subtitle: string;
  /** The text and translation the scene follows. */
  source: string;
  /** Shown before the scene starts. */
  intro: string;
  /** Honest framing where the companion is not a character in the story. */
  note?: string;
  start: string;
  /** Link to read the full chapter in the Scripture Explorer. */
  readMore: { label: string; href: string };
  moments: LeelaMoment[];
}

